using UnityEngine;using UnityEditor;using UnityEditor.Animations;using UnityEditor.SceneManagement;using System.IO;using System.Linq;
[InitializeOnLoad]public static class VillagerGestureSetup {
 const string E="Evidence/villager-gesture-20261030/",D="Assets/Demo/Characters/NPC/Villager/";
 static VillagerGestureSetup(){EditorApplication.delayCall+=Build;}
 static void Build(){if(EditorApplication.isPlayingOrWillChangePlaymode||File.Exists(E+"built.txt"))return;Directory.CreateDirectory(E);var scene=EditorSceneManager.OpenScene("Assets/Demo/Scenes/PrologueSettlement_TerracedInteriors.unity");File.Copy(scene.path,E+"scene-before.unity.txt",true);var witness=Object.FindObjectsOfType<DemoInteractable>().First(c=>c.clueId=="witness");var a=witness.GetComponentInChildren<Animator>();var controller=AnimatorController.CreateAnimatorControllerAtPath(AssetDatabase.GenerateUniqueAssetPath(D+"Villager_Gesture.controller"));var idle=AssetDatabase.LoadAssetAtPath<AnimationClip>("Assets/Demo/Characters/Hunter/Idle.anim");controller.layers[0].stateMachine.AddState("Idle").motion=idle;var layers=controller.layers;layers[0].iKPass=true;controller.layers=layers;var bindings=AnimationUtility.GetCurveBindings(idle).Where(b=>b.propertyName.Contains("Hand")&&b.propertyName.Contains("Stretched")).ToArray();
 for(int type=0;type<2;type++){var clip=new AnimationClip();clip.name=type==0?"Clasp fingers":"Left index pointing";foreach(var binding in bindings){if(type==1&&!binding.propertyName.StartsWith("Left"))continue;float value=type==0?(binding.propertyName.StartsWith("Left")?-.45f:-.85f):binding.propertyName.Contains("Index")?.9f:-.7f;AnimationUtility.SetEditorCurve(clip,binding,AnimationCurve.Constant(0,1,value));}var settings=AnimationUtility.GetAnimationClipSettings(clip);settings.loopTime=true;AnimationUtility.SetAnimationClipSettings(clip,settings);AssetDatabase.CreateAsset(clip,AssetDatabase.GenerateUniqueAssetPath(D+clip.name+".anim"));var mask=new AvatarMask();for(int i=0;i<(int)AvatarMaskBodyPart.LastBodyPart;i++)mask.SetHumanoidBodyPartActive((AvatarMaskBodyPart)i,false);mask.SetHumanoidBodyPartActive(AvatarMaskBodyPart.LeftFingers,true);if(type==0)mask.SetHumanoidBodyPartActive(AvatarMaskBodyPart.RightFingers,true);AssetDatabase.CreateAsset(mask,AssetDatabase.GenerateUniqueAssetPath(D+"GestureMask"+type+".mask"));controller.AddLayer(clip.name);layers=controller.layers;layers[layers.Length-1].avatarMask=mask;layers[layers.Length-1].defaultWeight=type==0?1:0;controller.layers=layers;layers[layers.Length-1].stateMachine.AddState("Pose").motion=clip;}
 a.runtimeAnimatorController=controller;a.applyRootMotion=false;var gesture=a.gameObject.AddComponent<VillagerGesture>();gesture.animator=a;gesture.interaction=witness;var player=Object.FindObjectOfType<DemoMovement>();gesture.player=player.transform;var clues=Object.FindObjectsOfType<DemoInteractable>();gesture.trail=clues.First(c=>c.clueId=="trail").transform;gesture.emblem=clues.First(c=>c.clueId=="emblem").transform;gesture.forestGoal=player.GetComponent<DemoPrologueFlow>().checkpoint;gesture.mentor=player.GetComponent<DemoPrologueFlow>().mentorClue.transform;
 // Prefab contains reusable pose logic; scene-only targets are assigned on the scene instance.
 string prefab=AssetDatabase.GenerateUniqueAssetPath(D+"NPC_Villager_Gesture.prefab");var copy=Object.Instantiate(a.gameObject);var cg=copy.GetComponent<VillagerGesture>();cg.interaction=null;cg.player=null;cg.trail=null;cg.emblem=null;cg.forestGoal=null;cg.mentor=null;PrefabUtility.SaveAsPrefabAsset(copy,prefab);Object.DestroyImmediate(copy);player.gameObject.AddComponent<VillagerGestureProbe>();EditorSceneManager.SaveScene(scene);AssetDatabase.SaveAssets();File.WriteAllText(E+"built.txt","Scene="+scene.path+" prefab="+prefab+"\nFinger muscle bindings="+bindings.Length+"\nLower=.45s; relaxed wait=1.5s; left-point blend=.55s. Original Activate event fires after recording clue.\n"+string.Join("\n",bindings.Select(b=>b.propertyName)));}
 [MenuItem("Vampire Demo/Finish Villager Gesture")]static void Finish(){if(EditorApplication.isPlaying)return;foreach(var probe in Object.FindObjectsOfType<VillagerGestureProbe>())Object.DestroyImmediate(probe);string path=EditorSceneManager.GetActiveScene().path;EditorSceneManager.SaveScene(EditorSceneManager.GetActiveScene());EditorSceneManager.OpenScene(path);object[] counts={0,0,0};typeof(Editor).Assembly.GetType("UnityEditor.LogEntries").GetMethod("GetCountsByType",System.Reflection.BindingFlags.Static|System.Reflection.BindingFlags.Public|System.Reflection.BindingFlags.NonPublic).Invoke(null,counts);File.WriteAllText(E+"saved.txt","Saved and reopened="+path+"; probe removed; errors="+counts[0]+" warnings="+counts[1]);}
}
